static void bk7258_gc2145_power_on(void)
{
  uint32_t before;
  uint32_t after;
  clock_t t0;
  clock_t t1;

  before = getreg32(BK7258_GPIO_CFG(DVP_POWER_PIN));
  bk7258_gpio_output(DVP_POWER_PIN, true);
  after = getreg32(BK7258_GPIO_CFG(DVP_POWER_PIN));
  printf("bk7258_camera_imgsensor: power_on GPIO%u GPIO_CFG before=0x%08x "
         "after=0x%08x (OUTPUT bit %s)\n",
         DVP_POWER_PIN, (unsigned int)before, (unsigned int)after,
         (after & BK7258_GPIO_OUTPUT) ? "SET" : "CLEAR");

  /* 120ms LDO settle delay, matching bk7258_gc2145.c's convention (see
   * that file's bk7258_gc2145_power_on() comment for the cross-checked
   * rationale, not repeated here).  Measured against clock_systime_ticks()
   * (SysTick-backed, CONFIG_USEC_PER_TICK=1000 -> 1 tick = 1ms,
   * independent of the up_udelay() busy-loop calibration this call
   * itself depends on) so the *actual* elapsed wall time of this delay
   * is directly visible in the log, rather than trusting the
   * CONFIG_BOARD_LOOPSPERMSEC estimate. */
  t0 = clock_systime_ticks();
  up_udelay(120000);
  t1 = clock_systime_ticks();
  printf("bk7258_camera_imgsensor: power_on 120ms delay done, measured "
         "%lu ticks (~%lu ms, 1 tick=%dus)\n",
         (unsigned long)(t1 - t0), (unsigned long)(t1 - t0),
         (int)(USEC_PER_TICK));
}

static void bk7258_gc2145_reset(void)
{
  uint32_t after_low;
  uint32_t after_high;
  clock_t t0;
  clock_t t1;

  bk7258_gpio_output(DVP_RESET_PIN, false);
  after_low = getreg32(BK7258_GPIO_CFG(DVP_RESET_PIN));
  printf("bk7258_camera_imgsensor: reset GPIO%u driven LOW, GPIO_CFG="
         "0x%08x (OUTPUT bit %s)\n",
         DVP_RESET_PIN, (unsigned int)after_low,
         (after_low & BK7258_GPIO_OUTPUT) ? "SET(!)" : "CLEAR(ok)");
  t0 = clock_systime_ticks();
  up_udelay(120000);
  t1 = clock_systime_ticks();
  printf("bk7258_camera_imgsensor: reset LOW-phase delay measured %lu "
         "ticks (~%lu ms)\n", (unsigned long)(t1 - t0),
         (unsigned long)(t1 - t0));

  bk7258_gpio_output(DVP_RESET_PIN, true);
  after_high = getreg32(BK7258_GPIO_CFG(DVP_RESET_PIN));
  printf("bk7258_camera_imgsensor: reset GPIO%u driven HIGH, GPIO_CFG="
         "0x%08x (OUTPUT bit %s)\n",
         DVP_RESET_PIN, (unsigned int)after_high,
         (after_high & BK7258_GPIO_OUTPUT) ? "SET(ok)" : "CLEAR(!)");
  t0 = clock_systime_ticks();
  up_udelay(120000);
  t1 = clock_systime_ticks();
  printf("bk7258_camera_imgsensor: reset HIGH-phase delay measured %lu "
         "ticks (~%lu ms)\n", (unsigned long)(t1 - t0),
         (unsigned long)(t1 - t0));
  printf("bk7258_camera_imgsensor: reset sequence complete\n");
}

static void bk7258_gc2145_dvp_pinmux(void)
{
  uint32_t i;

  /* GPIO27 (MCLK) uses a different pinmux function index than the
   * other DVP pins -- see this file's BK7258_SYS_REG_0X0A/0X0D comment
   * block for the full evidence chain.  DVP_PINMUX_FUNCTION (index 0,
   * GPIO_DEV_JPEG_MCLK) would NOT actually drive an oscillating clock
   * signal onto this pin; DVP_MCLK_PINMUX_FUNCTION (index 1,
   * GPIO_DEV_CLK_AUXS_CIS) is required, together with
   * bk7258_gc2145_mclk_enable() actually enabling that clock path's
   * gate. */
  bk7258_gpio_set_function(DVP_MCLK_PIN, DVP_MCLK_PINMUX_FUNCTION);
  bk7258_gpio_set_function(DVP_PCLK_PIN, DVP_PINMUX_FUNCTION);
  bk7258_gpio_set_function(DVP_HSYNC_PIN, DVP_PINMUX_FUNCTION);
  bk7258_gpio_set_function(DVP_VSYNC_PIN, DVP_PINMUX_FUNCTION);

  for (i = 0; i < 8; i++)
    {
      bk7258_gpio_set_function(DVP_DATA_PIN(i), DVP_PINMUX_FUNCTION);
    }
}

/* Enables the AUXS_CIS system clock path that supplies GC2145's MCLK
 * input (GPIO27), matching bk_avdk_smp's dvp_camera_mclk_enable()
 * MCLK_24M case exactly (cksel=3, ckdiv=19) -- see this file's
 * BK7258_SYS_REG_0X0A/0X0D comment block for the full rationale.  Must
 * be called after bk7258_gc2145_dvp_pinmux() has already selected
 * GPIO27's GPIO_DEV_CLK_AUXS_CIS function (pinmux alone does not start
 * the clock; this register sequence is the actual clock-source-select
 * + divider + gate-enable that makes the signal appear on the pin),
 * and before any I2C traffic (GC2145's datasheet power-up sequence
 * requires MCLK to be applied before the sensor's internal logic,
 * including its I2C/SCCB slave interface, becomes responsive). */
static void bk7258_gc2145_mclk_enable(void)
{
  uint32_t reg;

  reg = getreg32(BK7258_SYS_REG_0X0A);
  reg &= ~(BK7258_SYS_CKSEL_AUXS_CIS_MASK | BK7258_SYS_CKDIV_AUXS_CIS_MASK);
  reg |= (GC2145_MCLK_CKSEL << BK7258_SYS_CKSEL_AUXS_CIS_SHIFT) &
         BK7258_SYS_CKSEL_AUXS_CIS_MASK;
  reg |= (GC2145_MCLK_CKDIV << BK7258_SYS_CKDIV_AUXS_CIS_SHIFT) &
         BK7258_SYS_CKDIV_AUXS_CIS_MASK;
  putreg32(reg, BK7258_SYS_REG_0X0A);

  reg = getreg32(BK7258_SYS_REG_0X0D);
  reg |= BK7258_SYS_CIS_AUXS_CKEN;
  putreg32(reg, BK7258_SYS_REG_0X0D);

  printf("bk7258_camera_imgsensor: MCLK (GPIO%u) AUXS_CIS clock enabled, "
         "reg0x0a=0x%08x reg0x0d=0x%08x\n",
         DVP_MCLK_PIN, (unsigned int)getreg32(BK7258_SYS_REG_0X0A),
         (unsigned int)getreg32(BK7258_SYS_REG_0X0D));
}

static bool bk7258_gc2145_write_reg_table(const struct gc2145_reg *table,
                                           size_t count)
{
  size_t i;

  for (i = 0; i < count; i++)
    {
      if (!bk7258_i2c1_write_reg(GC2145_I2C_ADDR, table[i].reg,
                                 table[i].value))
        {
          return false;
        }
    }

  return true;
}

static bool bk7258_gc2145_is_available(FAR struct imgsensor_s *sensor)
{
  /* No readable chip-ID register is used by this driver's ported
   * register tables (see bk7258_gc2145.c's bk7258_gc9d01_test()-style
   * rationale for GC9D01: no RDID path was ever wired up for GC2145
   * either).  Report available unconditionally; the actual proof this
   * hardware exists and responds is whether bk7258_gc2145_init()'s
   * register writes succeed (return false there is what causes
   * capture_register() callers to see a failed device, not this
   * function). */
  return true;
}

static int bk7258_gc2145_init(FAR struct imgsensor_s *sensor)
{
  FAR struct bk7258_gc2145_dev_s *priv =
      (FAR struct bk7258_gc2145_dev_s *)sensor;

  printf("bk7258_camera_imgsensor: gc2145 power/reset/pinmux/i2c1 init\n");
  bk7258_gc2145_power_on();
  bk7258_gc2145_reset();
  bk7258_gc2145_dvp_pinmux();
  bk7258_gc2145_mclk_enable();

  printf("bk7258_camera_imgsensor: pre-i2c-init snapshot: GPIO%u(power) "
         "CFG=0x%08x GPIO%u(reset) CFG=0x%08x GPIO42(scl) CFG=0x%08x "
         "GPIO43(sda) CFG=0x%08x\n",
         DVP_POWER_PIN, (unsigned int)getreg32(BK7258_GPIO_CFG(DVP_POWER_PIN)),
         DVP_RESET_PIN, (unsigned int)getreg32(BK7258_GPIO_CFG(DVP_RESET_PIN)),
         (unsigned int)getreg32(BK7258_GPIO_CFG(42u)),
         (unsigned int)getreg32(BK7258_GPIO_CFG(43u)));

  bk7258_i2c1_init();

  printf("bk7258_camera_imgsensor: post-i2c-init snapshot: GPIO42(scl) "
         "CFG=0x%08x GPIO43(sda) CFG=0x%08x\n",
         (unsigned int)getreg32(BK7258_GPIO_CFG(42u)),
         (unsigned int)getreg32(BK7258_GPIO_CFG(43u)));

  if (!bk7258_i2c1_sda_idle_diag())
    {
      printf("bk7258_camera_imgsensor: WARNING: idle-bus SDA read-back "
             "was NOT reliably high (no clock/slave activity involved) "
             "-- ACK sampling is unreliable, any NACK below cannot be "
             "trusted as sensor behavior; suspect missing/broken "
             "pull-up on GPIO43 or the pin stuck low\n");
    }

  printf("bk7258_camera_imgsensor: writing %u init registers\n",
         (unsigned int)GC2145_INIT_REG_COUNT);
  if (!bk7258_gc2145_write_reg_table(g_gc2145_init_regs,
                                     GC2145_INIT_REG_COUNT))
    {
      printf("bk7258_camera_imgsensor: init register table write failed\n");
      return -EIO;
    }

  printf("bk7258_camera_imgsensor: writing %u resolution registers\n",
         (unsigned int)GC2145_640_480_REG_COUNT);
  if (!bk7258_gc2145_write_reg_table(g_gc2145_640_480_regs,
                                     GC2145_640_480_REG_COUNT))
    {
      printf("bk7258_camera_imgsensor: resolution register table write "
             "failed\n");
      return -EIO;
    }

  printf("bk7258_camera_imgsensor: gc2145 init complete\n");
  priv->initialized = true;
  return OK;
}

static int bk7258_gc2145_uninit(FAR struct imgsensor_s *sensor)
{
  FAR struct bk7258_gc2145_dev_s *priv =
      (FAR struct bk7258_gc2145_dev_s *)sensor;

  priv->initialized = false;
  return OK;
}

static FAR const char *
bk7258_gc2145_get_driver_name(FAR struct imgsensor_s *sensor)
{
  return "GC2145";
}

static int bk7258_gc2145_validate_frame_setting(
    FAR struct imgsensor_s *sensor, imgsensor_stream_type_t type,
    uint8_t nr_datafmts, FAR imgsensor_format_t *datafmts,
    FAR imgsensor_interval_t *interval)
{
  if (nr_datafmts < 1)
    {
      return -EINVAL;
    }

  /* Only 640x480 YUYV is supported -- this driver's register tables do
   * not implement any other resolution (see this file's header
   * comment). */
  if (datafmts[IMGSENSOR_FMT_MAIN].width != GC2145_CAPTURE_WIDTH ||
      datafmts[IMGSENSOR_FMT_MAIN].height != GC2145_CAPTURE_HEIGHT ||
      datafmts[IMGSENSOR_FMT_MAIN].pixelformat != IMGSENSOR_PIX_FMT_YUYV)
    {
      return -EINVAL;
    }

  return OK;
}

static int bk7258_gc2145_start_capture(
    FAR struct imgsensor_s *sensor, imgsensor_stream_type_t type,
    uint8_t nr_datafmts, FAR imgsensor_format_t *datafmts,
    FAR imgsensor_interval_t *interval)
{
  int ret;

  ret = bk7258_gc2145_validate_frame_setting(sensor, type, nr_datafmts,
                                              datafmts, interval);
  if (ret < 0)
    {
      return ret;
    }

  /* GC2145 has no separate streaming-enable register write in this
   * driver's ported tables -- the sensor begins outputting DVP data
   * continuously as soon as its init sequence completes in
   * bk7258_gc2145_init().  Capture start/stop is therefore entirely a
   * matter of whether the imgdata half (YUV_BUF/DMA) is listening, not
   * anything this function needs to tell the sensor. */

#include <nuttx/config.h>
#include <nuttx/arch.h>

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <nuttx/clock.h>

#include "bk7258_gpio.h"
#include "bk7258_i2c1.h"

/* GPIO42/GPIO43: plain GPIO bit-bang, NOT the I2C1_SCL/I2C1_SDA hardware
 * pinmux function -- see this file's header comment.  No
 * bk7258_gpio_set_function() call is made for either pin: leaving them
 * at their default/static function (whatever board bring-up left them
 * as, e.g. GPIO_DEV_LCD_G2/GPIO_DEV_LCD_B7 in the reference projects'
 * static tables) is fine because bk7258_gpio_output()/
 * bk7258_gpio_write() below unconditionally clear
 * BK7258_GPIO_SECOND_FUNCTION on every call, which is this repo's
 * equivalent of sim_i2c_driver.c's explicit gpio_dev_unmap() calls in
 * bk_i2c_init_v2(). */
#define BK7258_I2C1_SCL_PIN       42u
#define BK7258_I2C1_SDA_PIN       43u

/* Busy-wait spin count per SCL half-period.  sim_i2c_driver.c's
 * SCL_DELAY for 100kHz (CLK_DELAY_100K=25) is calibrated for that SDK's
 * own busy-wait loop body and CPU clock, which do not necessarily match
 * this NuttX build's optimization level or up_udelay() call overhead;
 * using up_udelay() with an explicit microsecond value instead of a
 * bare spin count is more portable across compilers/optimization
 * levels, at the cost of being slower than a tightly-tuned spin loop.
 * 5us per half-period is standard-mode I2C's *minimum* SCL high/low
 * time (100kHz nominal = 5us half-period exactly); GC2145 is not
 * timing-critical beyond standard-mode I2C compliance, so exact
 * matching to the reference driver's spin count is not required. */
#define BK7258_I2C1_HALF_PERIOD_US  5u

static void bk7258_i2c1_delay(void)
{
  up_udelay(BK7258_I2C1_HALF_PERIOD_US);
}

static void bk7258_i2c1_scl_high(void)
{
  bk7258_gpio_output(BK7258_I2C1_SCL_PIN, true);
}

static void bk7258_i2c1_scl_low(void)
{
  bk7258_gpio_output(BK7258_I2C1_SCL_PIN, false);
}

static void bk7258_i2c1_sda_high(void)
{
  bk7258_gpio_output(BK7258_I2C1_SDA_PIN, true);
}

static void bk7258_i2c1_sda_low(void)
{
  bk7258_gpio_output(BK7258_I2C1_SDA_PIN, false);
}

/* Release SDA to input (with the board's external 4.7K pull-up doing
 * the "release high" work, per this file's header comment on this
 * board's schematic-provided pull-ups) so this master can sample the
 * slave's ACK/NACK response during the 9th clock cycle -- matching
 * sim_i2c_driver.c's I2cSetSdaInput() before I2cReadSda(). */
static void bk7258_i2c1_sda_release(void)
{
  bk7258_gpio_input_pullup(BK7258_I2C1_SDA_PIN);
}

static bool bk7258_i2c1_sda_read(void)
{
  return bk7258_gpio_read(BK7258_I2C1_SDA_PIN);
}

/* I2C START condition: SDA high-to-low transition while SCL is high.
 * Matches sim_i2c_driver.c's I2cStart(). */
static void bk7258_i2c1_start(void)
{
  bk7258_i2c1_sda_high();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();

  bk7258_i2c1_sda_low();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();
}

/* I2C STOP condition: SDA low-to-high transition while SCL is high.
 * Matches sim_i2c_driver.c's I2cStop(). */
static void bk7258_i2c1_stop(void)
{
  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();

  bk7258_i2c1_sda_low();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();

  bk7258_i2c1_sda_high();
  bk7258_i2c1_delay();
}

/* Clock out one bit (MSB-first) and pulse SCL, matching
 * sim_i2c_driver.c's per-bit loop inside I2cSend(). */
static void bk7258_i2c1_write_bit(bool bit_value)
{
  if (bit_value)
    {
      bk7258_i2c1_sda_high();
    }
  else
    {
      bk7258_i2c1_sda_low();
    }

  bk7258_i2c1_delay();

  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();
}

/* Send one byte, MSB-first, then release SDA and sample the slave's ACK
 * bit on the 9th clock.  Returns true if the slave pulled SDA low
 * (ACK), false on NACK (SDA stayed high) -- matching sim_i2c_driver.c's
 * I2cSend() return value convention. */
static bool bk7258_i2c1_send_byte(uint8_t data)
{
  int bit;
  bool acked;

  for (bit = 7; bit >= 0; bit--)
    {
      bk7258_i2c1_write_bit((data & (1u << bit)) != 0);
    }

  bk7258_i2c1_sda_release();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();

  acked = !bk7258_i2c1_sda_read();

  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();

  /* Drive SDA again (it was left in input/released state above) before
   * the next write_bit()/stop() call assumes output control -- matches
   * sim_i2c_driver.c's I2cSend() calling I2cSetSdaOutput() right after
   * sampling ACK, for the same reason (I2cSetSdaHigh/Low() alone do not
   * return the pin to output mode once it has been released to input
   * for the ACK sample). */
  bk7258_i2c1_sda_high();

  return acked;
}

void bk7258_i2c1_init(void)
{
  /* No clock-gate/pinmux/interrupt setup needed: this is plain GPIO
   * bit-banging, not the hardware I2C1 peripheral (see this file's
   * header comment).  Idle the bus (both lines high) so the first
   * bk7258_i2c1_write_reg() call's START condition begins from a clean
   * idle state, matching sim_i2c_driver.c's I2cInit() (SetSdaOutput()
   * + SetSclOutput(), which this repo's bk7258_gpio_output(pin, true)
   * calls below achieve directly by driving both pins high). */
  bk7258_i2c1_sda_high();
  bk7258_i2c1_scl_high();
}

/* Diagnostic: with the bus idle (both lines driven high by init()),
 * release SDA (switch to input+internal-pull-up, exactly as
 * bk7258_i2c1_sda_release() does mid-transaction) and check whether it
 * reads back high.  This isolates one specific failure mode from the
 * "every I2C write NACKs" symptom: if this reads back LOW here, with
 * no slave/clock activity at all, the ACK-sampling mechanism itself is
 * unreliable (either no functioning pull-up -- internal or the
 * board's external 4.7K R42 -- or SDA is stuck low/shorted), which
 * would make every real transaction's NACK meaningless as evidence
 * about the sensor, since the "false" return could come from this
 * pre-existing condition rather than the sensor actually declining to
 * ACK.  If this reads back HIGH reliably, that failure mode is ruled
 * out and a real transaction's NACK is more likely a genuine
 * electrical/protocol issue (sensor not powered/reset, wrong address,
 * bad timing, etc). */
bool bk7258_i2c1_sda_idle_diag(void)
{
  int i;
  bool all_high = true;
  clock_t t0;
  clock_t t1;
  clock_t elapsed_ticks;

  /* Diagnostic: measure the *actual* wall-clock cost of 2000 calls to
   * bk7258_i2c1_delay() (the same function every SCL/SDA transition in
   * this driver waits on) against clock_systime_ticks() (SysTick-
   * backed, 1 tick = 1ms per CONFIG_USEC_PER_TICK, independent of the
   * up_udelay() busy-loop calibration being measured here).  At the
   * nominal 5us-per-call target, 2000 calls should take ~10ms (10
   * ticks).  This directly answers whether up_udelay(5) -- a small
   * value that only ever enters arm_udelay.c's innermost
   * "while (microseconds > 0)" branch, 5 iterations of a
   * CONFIG_BOARD_LOOPSPERMSEC-derived 12-iteration empty loop -- holds
   * up at this magnitude the same way the previously-verified 120ms
   * power/reset delays did, or whether compiler optimization/call
   * overhead at this small a loop count makes the actual SCL bit-bang
   * frequency far higher (or lower) than intended, independent of any
   * GPIO/pin/protocol correctness already ruled out. */
  t0 = clock_systime_ticks();
  for (i = 0; i < 2000; i++)
    {
      bk7258_i2c1_delay();
    }

  t1 = clock_systime_ticks();
  elapsed_ticks = t1 - t0;
  printf("bk7258_i2c1: 2000x bk7258_i2c1_delay() calls measured %lu "
         "ticks (~%lu ms); nominal target at 5us/call is ~10ms -- if "
         "this is far below 10ms, up_udelay(5) is running much faster "
         "than intended (SCL bit-bang far exceeds I2C standard-mode "
         "timing); if far above, much slower than intended\n",
         (unsigned long)elapsed_ticks, (unsigned long)elapsed_ticks);

  bk7258_i2c1_sda_high();
  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();

  bk7258_i2c1_sda_release();
  bk7258_i2c1_delay();

  for (i = 0; i < 8; i++)
    {
      bool level = bk7258_i2c1_sda_read();
      printf("bk7258_i2c1: idle-bus SDA read-back #%d = %d\n",
             i, (int)level);
      if (!level)
        {
          all_high = false;
        }

      bk7258_i2c1_delay();
    }

  bk7258_i2c1_sda_high();

  return all_high;
}

bool bk7258_i2c1_write_reg(uint8_t i2c_addr, uint8_t reg, uint8_t value)
{
  bool acked;

  bk7258_i2c1_start();

  acked = bk7258_i2c1_send_byte((uint8_t)(i2c_addr << 1));
  if (!acked)
    {
      bk7258_i2c1_stop();
      printf("bk7258_i2c1: NACK on address byte 0x%02x "
             "(i2c_addr=0x%02x, reg=0x%02x, value=0x%02x)\n",
             (unsigned int)(i2c_addr << 1), i2c_addr, reg, value);
      return false;
    }

  acked = bk7258_i2c1_send_byte(reg);
  if (!acked)
    {
      bk7258_i2c1_stop();
      printf("bk7258_i2c1: NACK on register-address byte 0x%02x "
             "(i2c_addr=0x%02x, value=0x%02x)\n",
             reg, i2c_addr, value);
      return false;
    }

  acked = bk7258_i2c1_send_byte(value);
  if (!acked)
    {
      printf("bk7258_i2c1: NACK on data byte 0x%02x "
             "(i2c_addr=0x%02x, reg=0x%02x)\n",
             value, i2c_addr, reg);
    }

  bk7258_i2c1_stop();

  return acked;
}

/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_camera_bringup.c
 *
 * Registration glue: wires the imgdata (bk7258_camera_imgdata_initialize(),
 * chip-layer) and imgsensor (bk7258_camera_imgsensor_initialize(),
 * board-layer) halves together and registers them under /dev/video0 via
 * the standard V4L2 capture_register() API (multi-instance registration
 * interface, per docs/zh-cn/device_dev_guide/media/camera/Camera_Driver.md
 * section 4's recommendation over the legacy single-instance
 * imgsensor_register()/imgdata_register()/capture_initialize() API).
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stddef.h>
#include <stdio.h>

#include <nuttx/video/imgdata.h>
#include <nuttx/video/imgsensor.h>
#include <nuttx/video/v4l2_cap.h>

#include "bk7258_camera_imgdata.h"
#include "bk7258_camera_bringup.h"

FAR struct imgsensor_s *bk7258_camera_imgsensor_initialize(void);

int bk7258_camera_initialize(void)
{
  FAR struct imgdata_s *imgdata;
  FAR struct imgsensor_s *imgsensor;
  FAR struct imgsensor_s *sensors[1];
  int ret;

  printf("bk7258_camera: registering /dev/video0\n");

  imgdata = bk7258_camera_imgdata_initialize();
  imgsensor = bk7258_camera_imgsensor_initialize();

  sensors[0] = imgsensor;

  ret = capture_register("/dev/video0", imgdata, sensors, 1);
  printf("bk7258_camera: capture_register() returned %d\n", ret);

  return ret;
}
  int ret = bk7258_bringup();

  if (ret < 0)
    {
      printf("board bring-up stopped, error=%d\n", ret);
      return;
    }

  printf("board bring-up initialization completed\n");

  /* GC9D01 QSPI panel bring-up smoke test.  board_app_finalinitialize()
   * (BOARDIOC_FINALINIT) is never invoked in this minimal, apps-less NSH
   * configuration (no CONFIG_BOARDCTL_FINALINIT, no apps/nshlib start-up
   * script caller), so the test entry point is invoked here instead, from
   * the unconditionally-called CONFIG_BOARD_LATE_INITIALIZE hook.  See
   * docs/superpowers/plans/2026-07-29-gc9d01-lcd-bringup.md Task 3 Step 3.
   */
  /* Disabled while isolating the QSPI command-completion wait from the
   * power-key motor polling worker. */
  /* (void)bk7258_gc9d01_test(0, NULL); */

  /* GC2145 camera: registered as a standard V4L2 /dev/video0 node here
   * (imgdata+imgsensor framework, see bk7258_camera_bringup.c), superseding
   * the older bare board_late_initialize() smoke-test call this line used
   * to make directly.  The old bk7258_gc2145_test() bare entry point is
   * kept as an independent NSH command (see bk7258_appinit.c) for
   * side-by-side diagnostic comparison, per design discussion in
   * docs/superpowers/plans/2026-07-30-gc2145-camera-bringup.md -- it is
   * intentionally NOT called from here anymore, so a bug in this new V4L2
   * driver cannot be masked by (or confused with) the old direct-call
   * path still running unconditionally at boot. */
  (void)bk7258_camera_initialize();
}
