  if (ack_flags == NULL)
    {
      return -EINVAL;
    }

  if (command != BK7258_MB_UART_DATA && command != BK7258_MB_UART_STATE)
    {
      g_uart.stats.bad_flags++;
      failed = true;
      malformed = true;
    }
