  if (first != count)
    {
      memcpy(data + first, g_uart.rx_ring, count - first);
    }

  g_uart.rx_read = (g_uart.rx_read + count) % MB_UART_RX_SIZE;
  if (status != NULL)
    {
      *status = g_uart.sticky_status;
      g_uart.sticky_status = 0;
    }

